"""Recipe model and executor. Input clips are generated by ffmpeg (lavfi), kept tiny."""

import json
from dataclasses import replace

import pytest
from pydantic import ValidationError

from src.studio import ffmpeg, recipe
from src.studio.recipe import FitVertical, Recipe, render
from tests.test_studio_ffmpeg import H264, needs_ffmpeg

FORBIDDEN = ("mirror", "flip", "speed", "setpts", "pitch", "atempo", "asetrate", "rubberband")


def make_clip(path, size, *, audio=True, duration=1):
    args = ["-f", "lavfi", "-i", f"testsrc2=size={size}:rate=25:duration={duration}"]
    if audio:
        args += ["-f", "lavfi", "-i", f"sine=frequency=440:duration={duration}",
                 "-c:a", "aac", "-shortest"]
    ffmpeg.run([*args, *H264, path], timeout_s=60)
    return path


def assert_spec(info, duration):
    assert (info.width, info.height) == (1080, 1920)
    assert info.fps == pytest.approx(30.0)
    assert info.video_codec == "h264"
    assert info.has_audio and info.audio_codec == "aac" and info.sample_rate == 48000
    assert info.duration == pytest.approx(duration, abs=0.1)


def test_registry_has_no_evasion_ops():
    assert "fit_vertical" in recipe.OPS
    for name in recipe.OPS:
        assert not any(bad in name.lower() for bad in FORBIDDEN), name


def test_unknown_op_lists_registered_ops():
    with pytest.raises(ValidationError, match="registered ops: .*fit_vertical"):
        Recipe.model_validate({"ops": [{"op": "hflip"}]})
    with pytest.raises(ValidationError):
        Recipe.model_validate({"ops": [{"op": "fit_vertical", "mode": "stretch"}]})
    with pytest.raises(ValidationError):
        Recipe.model_validate({"ops": []})


def test_json_round_trip():
    r = Recipe(ops=[FitVertical(mode="crop")])
    data = json.loads(json.dumps(r.model_dump()))
    assert data == {"version": 1, "ops": [{"op": "fit_vertical", "mode": "crop"}]}
    assert Recipe.model_validate(data) == r
    assert Recipe.model_validate_json(r.model_dump_json()) == r


def test_render_requires_source(tmp_path):
    with pytest.raises(ValueError, match="source"):
        render(Recipe(ops=[FitVertical()]), {}, tmp_path / "out.mp4")


@needs_ffmpeg
@pytest.mark.parametrize("mode", ["blur", "crop"])
@pytest.mark.parametrize("size", ["640x360", "360x360"])
def test_fit_vertical_output_spec(tmp_path, mode, size):
    src = make_clip(tmp_path / "in.mp4", size)
    out = tmp_path / "out.mp4"
    info = render(Recipe(ops=[FitVertical(mode=mode)]), {"source": src}, out,
                  timeout_s=120, preset="ultrafast")
    assert_spec(info, 1.0)
    assert info == ffmpeg.probe(out)
    assert sorted(p.name for p in tmp_path.iterdir()) == ["in.mp4", "out.mp4"]  # work dir gone


@needs_ffmpeg
def test_source_without_audio_gets_silent_track(tmp_path):
    src = make_clip(tmp_path / "in.mp4", "640x360", audio=False)
    info = render(Recipe(ops=[FitVertical()]), {"source": src}, tmp_path / "out.mp4",
                  timeout_s=120, preset="ultrafast")
    assert_spec(info, 1.0)


@needs_ffmpeg
def test_render_is_deterministic(tmp_path):
    src = make_clip(tmp_path / "in.mp4", "640x360")
    r = Recipe.model_validate({"ops": [{"op": "fit_vertical"}]})
    a = render(r, {"source": src}, tmp_path / "a.mp4", timeout_s=120, preset="ultrafast")
    b = render(r, {"source": src}, tmp_path / "b.mp4", timeout_s=120, preset="ultrafast")
    assert replace(a, size_bytes=0) == replace(b, size_bytes=0)


@needs_ffmpeg
def test_timeout_is_passed_through(tmp_path):
    src = make_clip(tmp_path / "in.mp4", "640x360", duration=2)
    with pytest.raises(ffmpeg.FFmpegTimeout):
        render(Recipe(ops=[FitVertical()]), {"source": src}, tmp_path / "out.mp4",
               timeout_s=0.01)
    assert not (tmp_path / "out.mp4").exists()
